                WHERE ("code" = "code_sel" OR ("code" IS NULL AND "code_sel" IS NULL)) AND ("created_at" = CAST("created_at_sel" AS timestamp without time zone) OR ("created_at" IS NULL AND CAST("created_at_sel" AS timestamp without time zone) IS NULL)) AND ("name" = "name_sel" OR ("name" IS NULL AND "name_sel" IS NULL)) AND ("updated_at" = CAST("updated_at_sel" AS timestamp without time zone) OR ("updated_at" IS NULL AND CAST("updated_at_sel" AS timestamp without time zone) IS NULL));
              IF found THEN
                
                RETURN;
              END IF;
              -- not there, so try to insert the key
              -- if someone else inserts the same key concurrently,
              -- we could get a unique-key failure
              BEGIN
                
                RETURN;
              EXCEPTION WHEN unique_violation THEN
                -- seamusabshere 9/20/12 only retry once
                IF (first_try = 1) THEN
                  first_try := 0;
                ELSE
                  RETURN;
                END IF;
                -- Do nothing, and loop to try the UPDATE again.
              END;
            END LOOP;
          END;
          $$;


