--
-- Name: final_calculation_views; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.final_calculation_views AS
 SELECT fc.id,
    fc.blank_id,
    rm.name AS raw_material_name,
    fc.color_description,
    rm.cost AS raw_material_cost,
    COALESCE(c1.cost_of_color, (0)::double precision) AS cost_of_color_one,
    COALESCE(c2.cost_of_color, (0)::double precision) AS cost_of_color_two,
    COALESCE(fc.percentage_of_colorant_one, (0)::double precision) AS percentage_of_colorant_one,
    COALESCE(fc.percentage_of_colorant_two, (0)::double precision) AS percentage_of_colorant_two,
    fc.number_of_pieces_per_unit_one,
    fc.number_of_pieces_per_unit_two
   FROM (((public.final_calculations fc
     LEFT JOIN public.colors c1 ON (((c1.name)::text = (fc.colorant_one)::text)))
     LEFT JOIN public.colors c2 ON (((c2.name)::text = (fc.colorant_two)::text)))
     LEFT JOIN public.raw_materials rm ON ((rm.id = fc.raw_material_id)));


--
-- Name: blank_average_costs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.blank_average_costs AS
 SELECT blank_id,
    (avg((((COALESCE(raw_material_cost, (0)::double precision) / (number_of_pieces_per_unit_one)::double precision) + ((COALESCE(cost_of_color_one, (0)::double precision) * COALESCE(percentage_of_colorant_one, (0)::double precision)) / (number_of_pieces_per_unit_one)::double precision)) + ((COALESCE(cost_of_color_two, (0)::double precision) * COALESCE(percentage_of_colorant_two, (0)::double precision)) / (number_of_pieces_per_unit_two)::double precision))))::numeric(10,5) AS average_cost_of_blank
   FROM public.final_calculation_views
  GROUP BY blank_id;


