CREATE VIEW public.item_with_box_costs AS
 SELECT t1.id,
    t1.item_number,
    t1.description,
    t2.name AS box_name,
    t1.number_of_pcs_per_box,
    (t1.ink_cost)::numeric(10,4) AS ink_cost,
    (t2.cost_per_box / (t1.number_of_pcs_per_box)::numeric) AS box_cost
   FROM (public.items t1
     LEFT JOIN public.boxes t2 ON ((t1.box_id = t2.id)));


