CREATE VIEW public.raw_material_views AS
 SELECT DISTINCT ON (t1.name) t1.id,
    t1.name,
    t4.name AS raw_material_type,
    t3.name AS vendor,
    t1.cost,
    t5.name AS unit,
    t2.name AS color
   FROM ((((public.raw_materials t1
     JOIN public.colors t2 ON ((t1.color_id = t2.id)))
     JOIN public.vendors t3 ON ((t1.vendor_id = t3.id)))
     JOIN public.rawmaterialtypes t4 ON ((t1.rawmaterialtype_id = t4.id)))
     JOIN public.units_of_measures t5 ON ((t1.units_of_measure_id = t5.id)));


