--
-- Name: item_with_job_counts _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.item_with_job_counts AS
 SELECT i.id,
    i.item_number,
    i.description,
    count(ij.item_id) AS number_of_jobs
   FROM (public.items i
     LEFT JOIN public.item_jobs ij ON ((ij.item_id = i.id)))
  GROUP BY i.id;


